Method.Implementation:
#dim tSC As %Status=$$$OK
$$$TRACE("Inside "_..%ConfigName_" Method ProcessTouchWorksRequest")
$$$TRACE(" Provider ID: "_pRequest.ProviderId)
$$$TRACE(" Merge PriorPatientID: "_pRequest.MergePriorPatientId)
$$$TRACE(" IDX PID: "_pRequest.IdxPid)

set pResponse=##class(IHC.ITF.Response.IdxDatabaseLookupResponse).%New()
if ($L(pRequest.ProviderId)>0){
	set tSC = ..ProcessTouchWorksAdtProviderLookup(pRequest, .providerIdLookupResp)
	set pResponse.EntryCodeIDForProviderId = providerIdLookupResp.StringValue
}
elseif ($L(pRequest.MergePriorPatientId)>0){
	set tSC = ..ProcessTouchWorksAdtOrgMrnLookup(pRequest, .mrgPriorPatientIdLookupResp)
	set pResponse.OrgMrnForMerge = mrgPriorPatientIdLookupResp.StringValue
	set pResponse.TwMrn = mrgPriorPatientIdLookupResp.StringValue
}
elseif ($L(pRequest.IdxPid)>0){
	set tSC = ..ProcessTouchWorksParientExistsinTW(pRequest, .patientExistsResp)
	if ($L(patientExistsResp.StringValue)>1){
		set pResponse.PatientExists = "Y"			
	}else{
		set pResponse.PatientExists = "N"
	}
	$$$TRACE(" pResponse.PatientExists : "_pResponse.PatientExists )
}
elseif ($L(pRequest.IdxPidSsn)>0){
	set tSC = ..ProcessTouchWorksPatientSsn(pRequest, .patientSsn)
	if ($L(patientSsn.StringValue)>1){
		set pResponse.ssn = patientSsn.StringValue		
	}else{
		set pResponse.ssn = ""
	}
	$$$TRACE(" pResponse.ssn : "_pResponse.ssn )
}	


Quit tSC

	#dim tSC As %Status=$$$OK
	set tSC=..Adapter.SetAutoCommit(1) 	

	$$$TRACE("Inside "_..%ConfigName_" Method ProcessTouchWorksPatientSsn")

	try{	
 	   set tSC=..Adapter.ExecuteQuery(.tResult,"SELECT a.SSN FROM dbo.Person a dbo.Person_XID b WHERE PERSONXID = '"_pRequest.IdxPidSsn_"' and a.ID=b.ID")
 	   $$$TRACE("  SUCCESS : "_tSC)		 	   	
	}CATCH err {		
	    $$$LOGERROR( "Error while Executing Query "  _ err.AsSystemError() _ " _ data: " _ err.Data _ "; code:" _ err.Code)
	    set tSC = $$$ERROR( "SQLError:Executing Query "  _ err.AsSystemError() _ " _ data: " _ err.Data _ "; code:" _ err.Code)	    
	}	
	$$$TRACE("  STATUS : "_tSC)	
	set pResponse=##class(Ens.StringResponse).%New()

	$$$TRACE("check tResult(ProcessTouchWorksParientSsn) "_tResult)
	If tResult.Next() {
     set pResponse.StringValue =  tResult.GetData(1)     
    } else {
     set pResponse.StringValue =  ""     
    }	

	$$$TRACE("  SSN in TW RESPONSE : "_pResponse.StringValue)	
	quit tSC

	#dim tSC As %Status=$$$OK
	set tSC=..Adapter.SetAutoCommit(1) 	

	$$$TRACE("Inside "_..%ConfigName_" Method ProcessTouchWorksParientExistsinTW")

	try{	
 	   set tSC=..Adapter.ExecuteQuery(.tResult,"SELECT PERSONXID FROM dbo.Person_XID WHERE PERSONXID = '"_pRequest.IdxPid_"'")
 	   $$$TRACE("  SUCCESS : "_tSC)		 	   	
	}CATCH err {		
	    $$$LOGERROR( "Error while Executing Query "  _ err.AsSystemError() _ " _ data: " _ err.Data _ "; code:" _ err.Code)
	    set tSC = $$$ERROR( "SQLError:Executing Query "  _ err.AsSystemError() _ " _ data: " _ err.Data _ "; code:" _ err.Code)	    
	}	
	$$$TRACE("  STATUS : "_tSC)	
	set pResponse=##class(Ens.StringResponse).%New()

	$$$TRACE("check tResult(ProcessTouchWorksParientExistsinTW) "_tResult)
	If tResult.Next() {
     set pResponse.StringValue =  tResult.GetData(1)     
    } else {
     set pResponse.StringValue =  ""     
    }	

	$$$TRACE("  PersonID in TW RESPONSE : "_pResponse.StringValue)	
	quit tSC

	#dim tSC As %Status=$$$OK
	set tSC=..Adapter.SetAutoCommit(1) 	

	$$$TRACE("Inside "_..%ConfigName_" Method ProcessTouchWorksAdtOrgMrnLookup..")

	try{	
 	   set tSC=..Adapter.ExecuteQuery(.tResult,"SELECT OrganizationMRN FROM Patient_Iorg where InternalOrganization = 0 and PersonID = (select ID from Person_XID where PersonXID = '"_pRequest.MergePriorPatientId_"' and regsystem = 'TouchWorks^OTHER')")
 	   $$$TRACE("  SUCCESS : "_tSC)		 	   	
	}CATCH err {		
	    $$$LOGERROR( "Error while Executing Query "  _ err.AsSystemError() _ " _ data: " _ err.Data _ "; code:" _ err.Code)
	    set tSC = $$$ERROR( "SQLError:Executing Query "  _ err.AsSystemError() _ " _ data: " _ err.Data _ "; code:" _ err.Code)	    
	}	
	$$$TRACE("  STATUS : "_tSC)	
	set pResponse=##class(Ens.StringResponse).%New()

	$$$TRACE("check tResult(ProcessTouchWorksAdtOrgMrnLookup) "_tResult)
	If tResult.Next() {
     set pResponse.StringValue =  tResult.GetData(1)     
    } else {
     set pResponse.StringValue =  ""     
    }	

	$$$TRACE("  Org Mrn Lookup RESPONSE : "_pResponse.StringValue)	
	quit tSC

	#dim tSC As %Status=$$$OK
	set tSC=..Adapter.SetAutoCommit(1) 	

	$$$TRACE("Inside "_..%ConfigName_" Method ProcessTouchWorksAdtProviderLookup..")

	try{	
 	   set tSC=..Adapter.ExecuteQuery(.tResult,"SELECT ID from Provider where EntryCode ='"_pRequest.ProviderId_"'")
 	   $$$TRACE("  SUCCESS : "_tSC)		 	   	
	}CATCH err {		
	    $$$LOGERROR( "Error while Executing Query "  _ err.AsSystemError() _ " _ data: " _ err.Data _ "; code:" _ err.Code)
	    set tSC = $$$ERROR( "SQLError:Executing Query "  _ err.AsSystemError() _ " _ data: " _ err.Data _ "; code:" _ err.Code)	    
	}	
	$$$TRACE("  STATUS : "_tSC)	
	set pResponse=##class(Ens.StringResponse).%New()

	$$$TRACE("check tResult "_tResult)
	If tResult.Next() {
     set pResponse.StringValue =  tResult.GetData(1)     
    } else {
     set pResponse.StringValue =  ""     
    }	

	$$$TRACE("  Provider Lookup RESPONSE : "_pResponse.StringValue)	
	quit tSC
